"""Independently specified transfer exercises: no solve-many wrapper.
Each row states a new application and at least three hand-specified fixtures.
Only Python and the library operations introduced by that point are required.
"""
TRANSFER = {}
def transfer(id, task, params, body, cases):
    TRANSFER[id] = dict(task=task, params=params, body=body, cases=cases)

transfer('next-target','Create two next-token pairs from a token list: one from the first width+1 tokens and one from the last width+1 tokens. Return both (input,target) pairs. width is positive and enough tokens exist.','tokens, width','first = tokens[:width+1]\nlast = tokens[-(width+1):]\nreturn (first[:-1],first[1:]), (last[:-1],last[1:])',[('[2,4,6,8,10],2','(([2,4],[4,6]),([6,8],[8,10]))'),('[9,7,5],1','(([9],[7]),([7],[5]))'),('[1,2],1','(([1],[2]),([1],[2]))')])
