transfer('dot','A query chooses between two candidate keys. Return their dot-product scores as a pair, preserving candidate order.','query, first, second','return (query*first).sum(), (query*second).sum()', [('torch.tensor([2.,1.]),torch.tensor([1.,3.]),torch.tensor([4.,0.])','(torch.tensor(5.),torch.tensor(8.))'),('torch.tensor([0.]),torch.tensor([8.]),torch.tensor([-3.])','(torch.tensor(0.),torch.tensor(0.))'),('torch.tensor([-1.,2.]),torch.tensor([2.,2.]),torch.tensor([1.,0.])','(torch.tensor(2.),torch.tensor(-1.))')])
