transfer('position-add','Embed a batch using absolute positions starting at offset instead of zero. Return token vectors plus the corresponding position vectors. The supplied tables cover every requested ID and position.','ids, token_table, position_table, offset','tokens = torch.nn.functional.embedding(ids,token_table)\npositions = torch.arange(ids.shape[-1])+offset\nreturn tokens+torch.nn.functional.embedding(positions,position_table)',[('torch.tensor([[0,0]]),torch.tensor([[2.]]),torch.tensor([[1.],[4.],[8.]]),1','torch.tensor([[[6.],[10.]]])'),('torch.tensor([[1]]),torch.tensor([[1.,1.],[3.,4.]]),torch.tensor([[2.,3.]]),0','torch.tensor([[[5.,7.]]])'),('torch.tensor([[0]]),torch.tensor([[0.]]),torch.tensor([[2.],[5.]]),1','torch.tensor([[[5.]]])')])
