transfer('accuracy','Return a list of incorrectly classified example indices in ascending order. Use argmax over class logits; labels are integer class IDs.','logits, labels','predicted = logits.argmax(dim=-1).tolist()\nreturn [i for i,(p,y) in enumerate(zip(predicted,labels.tolist())) if p!=y]',[('torch.tensor([[3.,1.],[1.,3.],[2.,0.]]),torch.tensor([0,0,1])','[1,2]'),('torch.tensor([[0.,4.]]),torch.tensor([1])','[]'),('torch.tensor([[2.,1.]]),torch.tensor([1])','[0]')])
