transfer('clip','Clip one combined gradient vector made by concatenating two parameter gradients, then return the clipped segments in their original shapes. Use one total norm, not one norm per segment. Both inputs are 1D.','first, second, max_norm','joined = torch.cat([first,second])\nnorm = torch.linalg.vector_norm(joined)\nclipped = joined*torch.clamp(max_norm/(norm+1e-12),max=1.)\nreturn clipped[:len(first)], clipped[len(first):]',[('torch.tensor([3.]),torch.tensor([4.]),1.','(torch.tensor([0.6]),torch.tensor([0.8]))'),('torch.tensor([0.3]),torch.tensor([0.4]),2.','(torch.tensor([0.3]),torch.tensor([0.4]))'),('torch.zeros(2),torch.zeros(1),1.','(torch.zeros(2),torch.zeros(1))')])
