transfer('adapter-count','Compute parameter savings across multiple bias-free projections using the same positive adapter rank. Return total full parameters, total adapter parameters, and their difference. Each projection is an (input_width,output_width) pair.','projections, rank','full = sum(i*o for i,o in projections)\nadapters = sum(rank*(i+o) for i,o in projections)\nreturn full, adapters, full-adapters',[('[(8,8),(4,6)],1','(88,26,62)'),('[(2,2)],1','(4,4,0)'),('[],2','(0,0,0)')])
